CREATE TABLE roles (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(80) NOT NULL UNIQUE);
CREATE TABLE permissions (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(80) NOT NULL UNIQUE);
CREATE TABLE role_permissions (role_id BIGINT NOT NULL, permission_id BIGINT NOT NULL, PRIMARY KEY(role_id,permission_id), FOREIGN KEY(role_id) REFERENCES roles(id), FOREIGN KEY(permission_id) REFERENCES permissions(id));
CREATE TABLE users (id BIGINT PRIMARY KEY AUTO_INCREMENT, email VARCHAR(254) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, role_id BIGINT NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(role_id) REFERENCES roles(id));
CREATE TABLE sessions (token_hash CHAR(64) PRIMARY KEY, user_id BIGINT NOT NULL, expires_at DATETIME NOT NULL, INDEX(expires_at), FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE buildings (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(120) NOT NULL UNIQUE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE locations (id BIGINT PRIMARY KEY AUTO_INCREMENT, building_id BIGINT NOT NULL, name VARCHAR(120) NOT NULL, UNIQUE(building_id,name), FOREIGN KEY(building_id) REFERENCES buildings(id));
CREATE TABLE devices (id BIGINT PRIMARY KEY AUTO_INCREMENT, asset_id VARCHAR(80) NOT NULL UNIQUE, name VARCHAR(120) NOT NULL, manufacturer VARCHAR(80) NOT NULL DEFAULT '', model VARCHAR(80) NOT NULL DEFAULT '', serial_number VARCHAR(120) NOT NULL DEFAULT '', management_ip VARCHAR(45) NOT NULL DEFAULT '', category VARCHAR(50) NOT NULL, location_id BIGINT NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'unknown', notes TEXT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(location_id) REFERENCES locations(id), INDEX(location_id,status), INDEX(category));
CREATE TABLE audit_logs (id BIGINT PRIMARY KEY AUTO_INCREMENT, user_id BIGINT NOT NULL, action VARCHAR(100) NOT NULL, target VARCHAR(120) NOT NULL, result VARCHAR(30) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX(created_at), FOREIGN KEY(user_id) REFERENCES users(id));
INSERT INTO roles(name) VALUES ('Super Administrator'),('Network Administrator'),('Network Engineer'),('IT Technician'),('Management / Supervisor'),('Read-only Viewer');
INSERT INTO permissions(name) VALUES ('inventory.read'),('inventory.write'),('users.manage'),('audit.read');
INSERT INTO role_permissions SELECT r.id,p.id FROM roles r CROSS JOIN permissions p WHERE r.id=1 OR (r.id=2 AND p.name IN ('inventory.read','inventory.write','audit.read')) OR (r.id IN (3,4) AND p.name IN ('inventory.read','inventory.write')) OR (r.id IN (5,6) AND p.name='inventory.read');
